<?php require_once __DIR__.'/../_bootstrap.php';$u=user();$s=db()->prepare('SELECT s.*,p.name,p.brand,p.category,p.unique_identifier,p.identifier_type,u.full_name seller_name,u.shop_name FROM sales s JOIN products p ON p.id=s.product_id JOIN users u ON u.id=s.seller_id WHERE s.seller_id=? ORDER BY s.sold_at DESC');$s->execute([$u['id']]);out(['success'=>true,'sales'=>$s->fetchAll()]);
